package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.patron.Patron;
import net.officefloor.hq.app.patron.PatronRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.plan.PlanService;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.crew.CrewService;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.snapshot.PersonSnapshotService;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.watch.WatchRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Merging one person of a sheet into another. */
@Service
public class PersonMergeService {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final PatronRepository patrons;
    private final PoolMemberRepository poolMembers;
    private final CrewService crews;
    private final StatementService statements;
    private final WatchRepository watches;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final RoleService roles;
    private final Audit audit;
    private final Rollup rollup;
    private final PlanService plans;
    private final PersonSnapshotService snapshots;
    private final PeriodRepository periods;

    public PersonMergeService(PersonRepository people, ClaimRepository claims, PatronRepository patrons,
            PoolMemberRepository poolMembers, CrewService crews, StatementService statements, WatchRepository watches,
            SheetService sheets, SheetRepository sheetStore, RoleService roles, Audit audit, Rollup rollup,
            PlanService plans, PersonSnapshotService snapshots, PeriodRepository periods) {
        this.periods = periods;
        this.plans = plans;
        this.snapshots = snapshots;
        this.people = people;
        this.claims = claims;
        this.patrons = patrons;
        this.poolMembers = poolMembers;
        this.crews = crews;
        this.statements = statements;
        this.watches = watches;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.roles = roles;
        this.audit = audit;
        this.rollup = rollup;
    }

    /**
     * A steward merges a person into another of the sheet. The merged person's claims move to the other, keeping
     * their numbers and dates, listed as the other's newest in the order they were added, each keeping any figure a
     * statement bound it to; their statements move to the other, whose count becomes their own plus the merged
     * person's and whose last statement stays theirs (or, having none, becomes the merged person's last); their name and aliases become aliases of the other; their patrons are added to the
     * other's (never the other themselves, nor one twice), anyone naming them as patron names the other instead (once),
     * and their pool memberships move to the other (shares added where the other is already a member). Their
     * figures fixed by a closed or soft-closed period are added to the other's there. Their
     * holds, watchers, snapshot lines and contact are dropped with them. Refused for anyone but a steward, a merge into
     * the same person, and when either of them is retired.
     */
    @Transactional
    public Person merge(String sheetId, String user, long id, long intoId) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge people");
        }
        Person from = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        Person into = people.findByIdAndSheetId(intoId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (from.getId().equals(into.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves");
        }
        if (from.isRetired() || into.isRetired()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged");
        }
        Rollup.Figures before = rollup.of(sheetId);

        long listed = claims.lastListed(sheetId);
        List<Claim> moving = claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, from.getId()).stream()
                .sorted(Comparator.comparing(Claim::getId)).toList();
        for (Claim claim : moving) {
            claim.reassign(into.getId(), ++listed);
        }
        claims.saveAll(moving);

        // The patron pairs the other has once the merged person's are taken over.
        List<Patron> sheetPatrons = patrons.findBySheetIdOrderByIdAsc(sheetId);
        Set<List<Long>> pairs = new LinkedHashSet<>();
        sheetPatrons.stream().filter(p -> !p.getPersonId().equals(from.getId()) && !p.getPatronId().equals(from.getId()))
                .forEach(p -> pairs.add(List.of(p.getPersonId(), p.getPatronId())));
        List<Patron> gone = new ArrayList<>();
        List<Patron> added = new ArrayList<>();
        for (Patron p : sheetPatrons) {
            if (!p.getPersonId().equals(from.getId()) && !p.getPatronId().equals(from.getId())) {
                continue;
            }
            gone.add(p);
            long person = p.getPersonId().equals(from.getId()) ? into.getId() : p.getPersonId();
            long patron = p.getPatronId().equals(from.getId()) ? into.getId() : p.getPatronId();
            if (person != patron && pairs.add(List.of(person, patron))) {
                added.add(new Patron(sheetId, person, patron));
            }
        }
        patrons.deleteAll(gone);
        patrons.flush();

        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
            var existing = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
            if (existing.isPresent()) {
                existing.get().setShare(existing.get().getShare().add(member.getShare()));
                poolMembers.delete(member);
            } else {
                member.moveTo(into.getId());
            }
        }
        poolMembers.flush();
        crews.reassign(from.getId(), into.getId());

        statements.move(sheetId, from.getId(), sheetId, into.getId());
        snapshots.dropOf(sheetId, from.getId());
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
        plans.reassign(from.getId(), into.getId());
        // A closed or soft-closed period keeps the merged person's fixed figures, now the other's.
        List<Period> fixed = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().filter(Period::isFixed).toList();
        fixed.forEach(period -> period.mergePerson(from.getId(), into.getId()));
        periods.saveAll(fixed);
        String fromName = from.getName();
        List<String> fromAliases = from.getAliases();
        people.delete(from);
        people.flush();

        patrons.saveAll(added);
        into.addAlias(fromName);
        fromAliases.forEach(into::addAlias);
        Person merged = people.saveAndFlush(into);
        audit.recordChangeOnCommit(sheetId, user, "PERSON_MERGED sheet=" + sheetId + " by=" + user
                + " from=" + fromName + " into=" + merged.getName());
        rollup.recordChanges(sheetId, user, before);
        return merged;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and a grade (A, B or C), dated: each grade is in force from its from-date. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The person's place in the sheet's list: the list is in ascending position. */
    @Column(name = "position", nullable = false)
    private int position;

    /** The sheet the person was last transferred from; null when they were never transferred. */
    @Column(name = "origin_sheet_id")
    private String originSheetId;

    /** The sheet's today on the sheet the person was last transferred to, when they arrived; null when never. */
    @Column(name = "arrived_on")
    private LocalDate arrivedOn;

    /** The grades recorded for the person; the first given has no from-date (from the beginning of time). */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's dated terms: each in force from its from-date until the next one's, ahead of the undated. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_terms", joinColumns = @JoinColumn(name = "person_id"))
    private List<TermsFrom> datedTerms = new ArrayList<>();

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The person's tags: trimmed, lower-cased, without repeats, sorted and joined by commas; none when they have
     *  none. */
    @Column(name = "tags", length = 1000)
    private String tags;

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The retirements the person was unretired from: a claim dated within one is refused. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_past_retirement", joinColumns = @JoinColumn(name = "person_id"))
    private List<PastRetirement> pastRetirements = new ArrayList<>();

    /** The person's holds: their open claims dated within one, and not bound by a statement, count in no live due
     *  figure (they still count in what is claimed). */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    /** The reason a steward flagged the person for; null when never flagged. */
    @Column(name = "flag_reason", length = 200)
    private String flagReason;

    /** The last day the flag is in force; null when never flagged. */
    @Column(name = "flag_until")
    private LocalDate flagUntil;

    /** The user who may approve or reject the person's PENDING claims as a steward may; null when none. */
    @Column(name = "approver", length = 100)
    private String approver;

    /** The other names the person is found by, stored trimmed. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias", nullable = false)
    private Set<String> aliases = new HashSet<>();

    /** Raised on every save; an edit made from an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(null, grade));
    }

    /** A copy of the person on another sheet, unsaved: their name, place in the list, grades, terms, contact, tags,
     *  aliases, holds and retirements (current and past); not where they came from. */
    public Person copyTo(String sheetId) {
        Person copy = new Person();
        copy.sheetId = sheetId;
        copy.name = name;
        copy.position = position;
        grades.forEach(g -> copy.grades.add(new GradeFrom(g.getFromDate(), g.getGrade())));
        copy.terms = terms;
        datedTerms.forEach(t -> copy.datedTerms.add(new TermsFrom(t.getFromDate(), t.getTerms())));
        copy.contact = contact;
        copy.tags = tags;
        copy.retiredFrom = retiredFrom;
        pastRetirements.forEach(r -> copy.pastRetirements.add(new PastRetirement(r.getFromDate(), r.getToDate())));
        holds.forEach(h -> copy.holds.add(new Hold(h.getFromDate(), h.getToDate())));
        copy.aliases.addAll(aliases);
        copy.flagReason = flagReason;
        copy.flagUntil = flagUntil;
        copy.approver = approver;
        return copy;
    }

    public Long getId() {
        return id;
    }

    /** Give an unsaved person rebuilt from the sheet's history the id it had then, so its figures are worked out as
     *  the live one's are; it is never saved. */
    public void rebuiltWithId(long id) {
        this.id = id;
    }

    public String getSheetId() {
        return sheetId;
    }

    /** Move the person to another sheet, leaving their holds behind; the sheet they leave becomes their origin. */
    public void transferTo(String sheetId, LocalDate arrivedOn) {
        this.originSheetId = this.sheetId;
        this.sheetId = sheetId;
        this.arrivedOn = arrivedOn;
        this.holds.clear();
    }

    public LocalDate getArrivedOn() {
        return arrivedOn;
    }

    public String getOriginSheetId() {
        return originSheetId;
    }

    public int getPosition() {
        return position;
    }

    public void setPosition(int position) {
        this.position = position;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, in the order they take effect. */
    public List<GradeFrom> getGrades() {
        return grades.stream().sorted(GradeFrom.BY_FROM).toList();
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it. A null date
     *  takes the latest grade recorded. */
    public String gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> date == null || g.getFromDate() == null || !g.getFromDate().isAfter(date))
                .max(GradeFrom.BY_FROM)
                .orElseGet(() -> grades.stream().min(GradeFrom.BY_FROM).orElseThrow())
                .getGrade();
    }

    /** Record {@code grade} from {@code from}, replacing the grade recorded from that same date, if any. */
    public void setGradeFrom(LocalDate from, String grade) {
        grades.removeIf(g -> Objects.equals(g.getFromDate(), from));
        grades.add(new GradeFrom(from, grade));
    }

    /** Every grade recorded as {@code from} becomes {@code into}, keeping its from-date. */
    public void regrade(String from, String into) {
        List<GradeFrom> regraded = grades.stream()
                .map(g -> from.equals(g.getGrade()) ? new GradeFrom(g.getFromDate(), into) : g)
                .toList();
        grades.clear();
        grades.addAll(regraded);
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The dated terms recorded, in the order they take effect. */
    public List<TermsFrom> getDatedTerms() {
        return datedTerms.stream().sorted(TermsFrom.BY_FROM).toList();
    }

    /** Record {@code terms} (null: none of their own) from {@code from}, replacing those recorded from that same
     *  date, if any. */
    public void setTermsFrom(LocalDate from, Integer terms) {
        datedTerms.removeIf(t -> t.getFromDate().equals(from));
        datedTerms.add(new TermsFrom(from, terms));
    }

    /** The person's own terms in force on {@code date}: the dated ones with the latest from-date on or before it,
     *  else the undated ones; null when none are in force. A null date takes the latest terms recorded. */
    public Integer termsOn(LocalDate date) {
        TermsFrom dated = datedTerms.stream()
                .filter(t -> date == null || !t.getFromDate().isAfter(date))
                .max(TermsFrom.BY_FROM)
                .orElse(null);
        return dated != null ? dated.getTerms() : terms;
    }

    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    /** The person's tags, sorted; empty when they have none. */
    public List<String> tagList() {
        return tags == null ? List.of() : List.of(tags.split(","));
    }

    /** The person's aliases, sorted as names are compared: without regard to case (those differing only in case
     *  in their natural order). */
    public List<String> getAliases() {
        return aliases.stream().sorted(String.CASE_INSENSITIVE_ORDER.thenComparing(Comparator.naturalOrder())).toList();
    }

    public void addAlias(String alias) {
        aliases.add(alias);
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Retired as soon as a retirement date is set, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** The retirements the person was unretired from, in the order they started. */
    public List<PastRetirement> getPastRetirements() {
        return pastRetirements.stream().sorted(PastRetirement.BY_FROM).toList();
    }

    public void addPastRetirement(PastRetirement retirement) {
        pastRetirements.add(retirement);
    }

    /** End the retirement on {@code on}: it is kept as a past retirement, and the person is no longer retired. */
    public void unretire(LocalDate on) {
        pastRetirements.add(new PastRetirement(retiredFrom, on));
        retiredFrom = null;
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The holds recorded, in the order they start. */
    public List<Hold> getHolds() {
        return holds.stream().sorted(Hold.BY_FROM).toList();
    }

    public void addHold(Hold hold) {
        holds.add(hold);
    }

    /** The user who may approve or reject the person's PENDING claims; null when none. */
    public String getApprover() {
        return approver;
    }

    /** Set the person's approver (null: none). */
    public void setApprover(String approver) {
        this.approver = approver;
    }

    /** Whether {@code user} is the person's approver. */
    public boolean isApprover(String user) {
        return approver != null && user != null && approver.equals(user.trim());
    }

    /** Flag the person with a reason until a date, replacing any flag they had. */
    public void flag(String reason, LocalDate until) {
        this.flagReason = reason;
        this.flagUntil = until;
    }

    /** The reason the person is flagged for on {@code today}: while today is on or before the until-date; null
     *  otherwise. */
    public String flagOn(LocalDate today) {
        return flagReason != null && flagUntil != null && today != null && !today.isAfter(flagUntil)
                ? flagReason : null;
    }

    /** Whether a claim of this person counts in the live totals on the sheet's {@code today}: an OPEN one does not
     *  once {@code today} reaches the retirement date, unless a statement binds it. A hold (theirs or the claim's
     *  own) does not take it out: holds only change the pools' cuts. */
    public boolean counts(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && (claim.isStated() || !heldOn(claim, today));
    }

    /** Whether a claim of this person counts in what they have claimed on the sheet's {@code today}: as in the live
     *  totals, except that a hold (theirs or the claim's own) does not take it out. */
    public boolean countsClaimed(Claim claim, LocalDate today) {
        return claim.getStatus().counts()
                && (claim.isStated() || !(claim.getStatus().isOpen() && retiredOn(today)));
    }

    /** Whether a claim of this person counts in the figures of a period ending {@code end}: by the status it had at
     *  the end of that day, left out when retired as the live totals on the sheet's {@code today} say. */
    public boolean countsAtEnd(Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus at = claim.statusAt(end);
        return at != null && at.counts() && (claim.isStated() || !heldOn(claim, today));
    }

    /** Whether a claim of this person counts as a new statement finds it: as when no statement binds it, except that
     *  an open claim a statement binds still counts once {@code today} reaches the retirement date. */
    public boolean countsUnbound(Claim claim, LocalDate today) {
        return claim.getStatus().counts()
                && !(claim.getStatus().isOpen() && !claim.isStated() && retiredOn(today));
    }

    /** Whether the claim is open once {@code today} reaches the person's retirement date. */
    private boolean heldOn(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && retiredOn(today);
    }

    /** Whether a hold of the person is in force on {@code date}: one whose dates include it. */
    public boolean heldOn(LocalDate date) {
        return date != null && holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Whether the retirement date is reached on {@code date}: set, and on or before it. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    /** Whether a claim dated {@code date} is refused: one dated after the retirement date, or after the from-date
     *  and before the to-date of a past retirement. */
    public boolean refusesClaimOn(LocalDate date) {
        return (retiredFrom != null && date.isAfter(retiredFrom))
                || pastRetirements.stream().anyMatch(r -> r.refusesClaimOn(date));
    }
}

